############################################################ # PG Setup Code ############################################################ Context("Numeric"); $a = random(3,6,1); $ans = Compute("$a*x^($a-1)"); $popup1 = PopUp(['?','True','False'],2); $popup2 = PopUp(['?','True','False'],1); $popup3 = PopUp(['?','True','False'],1); $popup4 = PopUp(['?','True','False'],2);
